import json, math
from pathlib import Path
import nbformat
import pandas as pd

# Load executed notebook
nb = nbformat.read('modelo_medicina_executed.ipynb', as_version=4)

# Extract all validation outputs systematically
results = {
    'strict_filter': True,
    'filter_criteria': "NBC='MEDICINA' AND NOMBRE_PROGRAMA_ACAD contains 'MEDICINA'",
}

for i, cell in enumerate(nb.cells):
    if cell.cell_type == 'code':
        src = ''.join(cell.get('source', []))
        texts = []
        for out in cell.get('outputs', []):
            if out.output_type == 'stream':
                texts.append(out.text.strip())
            elif out.output_type in ('execute_result', 'display_data') and 'text/plain' in out.get('data', {}):
                t = out['data']['text/plain']
                if isinstance(t, list): t = ''.join(t)
                texts.append(t.strip()[:800])
        combined = '\n'.join(texts)

        # Extract key metrics from various cells
        if 'Filas medicina:' in combined:
            for line in combined.split('\n'):
                if 'Filas medicina:' in line:
                    results['solo_medicina_rows'] = int(line.split(':')[1].strip())
        if 'Filas en medicina_anual:' in combined:
            for line in combined.split('\n'):
                if 'Filas en medicina_anual:' in line:
                    results['medicina_anual_rows'] = int(line.split(':')[1].strip())
        if 'Filas en medicina_features:' in combined:
            for line in combined.split('\n'):
                if 'Filas en medicina_features:' in line:
                    results['medicina_features_rows'] = int(line.split(':')[1].strip())
        if 'Programas únicos con historia:' in combined:
            for line in combined.split('\n'):
                if 'Programas únicos con historia:' in line:
                    results['programas_unicos'] = int(line.split(':')[1].strip())
        if 'Filas disponibles para modelado:' in combined:
            for line in combined.split('\n'):
                if 'Filas disponibles para modelado:' in line:
                    results['modeling_rows'] = int(line.split(':')[1].strip())
        if 'Filas validación:' in combined and 'Filas test:' in combined:
            for line in combined.split('\n'):
                if 'Filas validación:' in line:
                    results['validation_rows'] = int(line.split(':')[1].strip())
                if 'Filas test:' in line:
                    results['test_rows'] = int(line.split(':')[1].strip())
        if 'Residuo medio test:' in combined:
            for line in combined.split('\n'):
                if 'Residuo medio test:' in line:
                    results['test_residual_mean'] = float(line.split(':')[1].strip())
        if 'Mejora MAE vs baseline en test:' in combined:
            for line in combined.split('\n'):
                if 'Mejora MAE vs baseline en test:' in line:
                    results['test_mae_improvement_vs_baseline'] = float(line.split(':')[1].strip())
        if 'Recomendaciones generadas:' in combined:
            for line in combined.split('\n'):
                if 'Recomendaciones generadas:' in line:
                    results['recommendations_count'] = int(line.split(':')[1].strip())
        if 'Con predicción test:' in combined:
            for line in combined.split('\n'):
                if 'Con predicción test:' in line:
                    results['recommendations_with_test'] = int(line.split(':')[1].strip())
        if 'Sin predicción test:' in combined:
            for line in combined.split('\n'):
                if 'Sin predicción test:' in line:
                    results['recommendations_without_test'] = int(line.split(':')[1].strip())
        if 'MODEL_VALIDATION_ANALYSIS_OK' in combined:
            results['model_validation_analysis'] = 'OK'
        if 'FEATURE_ENGINEERING_VALIDATION_OK' in combined:
            results['feature_engineering_validation'] = 'OK'
        if 'RECOMMENDATIONS_VALIDATION_OK' in combined:
            results['recommendations_validation'] = 'OK'
        if 'ARTIFACT_EXPORT_VALIDATION_OK' in combined:
            results['artifact_export_validation'] = 'OK'

# Load old validation_results to get model metrics
old_val = json.loads(Path('validation_results.json').read_text())
results['best_model'] = old_val.get('best_model_by_validation_mae', 'Random Forest')
results['validation_mae'] = old_val.get('best_validation_metrics', {}).get('MAE')
results['test_mae'] = old_val.get('best_test_metrics', {}).get('MAE')
results['test_r2'] = old_val.get('best_test_metrics', {}).get('R2')

# Update validation_results.json with strict filter info
new_val = old_val.copy()
new_val.update({
    'strict_filter_applied': True,
    'filter_criteria': "NBC='MEDICINA' AND NOMBRE_PROGRAMA_ACAD contains 'MEDICINA'",
    'solo_medicina_shape': [results['solo_medicina_rows'], 24],
    'medicina_anual_shape': [results['medicina_anual_rows'], 19],
    'medicina_features_shape': [results['medicina_features_rows'], 28],
    'programas_unicos_features': results['programas_unicos'],
    'validation_rows': results['validation_rows'],
    'test_rows': results['test_rows'],
    'test_residual_mean': results['test_residual_mean'],
    'test_mae_improvement_vs_baseline': results['test_mae_improvement_vs_baseline'],
    'recommendations_count': results['recommendations_count'],
    'recommendations_with_test': results['recommendations_with_test'],
    'recommendations_without_test': results['recommendations_without_test'],
})

# Clean NaN/Inf for JSON
def clean_json(obj):
    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            return None
        return obj
    elif isinstance(obj, dict):
        return {k: clean_json(v) for k, v in obj.items()}
    elif isinstance(obj, list):
        return [clean_json(v) for v in obj]
    return obj

new_val = clean_json(new_val)

# Write updated validation_results.json
Path('validation_results.json').write_text(json.dumps(new_val, ensure_ascii=False, indent=2) + '\n')
Path('artifacts/validation_results.json').write_text(json.dumps(new_val, ensure_ascii=False, indent=2) + '\n')

print('Updated validation_results.json with strict filter results')
print(json.dumps(results, indent=2))
